#!/bin/sh
# PROTOTYPE art for the Agent World town (ticket "How places are built"). Runs Codex image jobs in parallel.
cd "$(dirname "$0")"
gen() { [ -f "$1.png" ] && { echo "$1 exists"; return; }; codex exec -s workspace-write --skip-git-repo-check "Use your image generation tool to create this image, then save the PNG as ./$1.png. Do not edit any other file. Image: $2" > "$1.log" 2>&1; echo "$1 exit $?"; }
STYLE="Original artwork. Crisp 16-bit pixel art in a cozy storybook life-sim style, warm evening palette (amber, moss green, teal, lavender, peach, warm stone), clean dark outlines, consistent light from the top left. Classic 3/4 top-down RPG view like Stardew Valley town maps: you see the front wall and the roof from above at an angle. No text, no letters, no logos, no UI, no watermark."
BG="Each object is separate with generous empty space around it, on a flat pure magenta #FF00FF background with no shadows on the background and no magenta in the objects."
gen houses-small "Sprite sheet of 4 different small cozy cottages for a town map, each about square, each with a door at the bottom centre of the front wall, two windows, crooked tiled roofs in different colours (terracotta, slate blue, moss green, plum), ivy and flower boxes. $BG $STYLE" &
gen houses-medium "Sprite sheet of 3 different medium two-storey town houses for a town map, each with a door at the bottom centre of the front wall, several windows, timber framing, steep roofs with chimneys and dormers, hanging lanterns, flower boxes. $BG $STYLE" &
gen hq "One large grand guild hall building for a town map: stone ground floor and timber upper floor, big arched double door at the bottom centre, tall arched windows, steep purple slate roof with a small bell tower, purple banners, lanterns, ivy. The left and right walls are plain and flat so smaller annex buildings can be placed directly against them. Centered, filling most of the image. $BG $STYLE" &
gen wings "Sprite sheet of 4 different small annex buildings that match a grand guild hall (stone ground floor, timber upper floor, purple slate roofs, purple banners): each is a narrow one-and-a-half storey wing with its own small door at the bottom centre and one or two windows; the left and right walls are plain so they can stand directly against other buildings. $BG $STYLE" &
gen hub-questboard "One open wooden pavilion for a town map: a large notice board covered in pinned parchment quest notes, a small roof over it, a lantern, crates and a bench beside it. Centered. $BG $STYLE" &
gen hub-forge "One blacksmith forge building for a town map: stone walls, open front with a glowing furnace, an anvil outside the front, a tall chimney with smoke, tools hanging, barrels. Door at the bottom centre. Centered. $BG $STYLE" &
gen hub-library "One grand library building for a town map: pale stone, a teal dome, tall arched windows glowing warmly, columns flanking an arched door at the bottom centre, stacks of books visible through windows, ivy. Centered. $BG $STYLE" &
gen hub-square "One town square centrepiece for a town map: a round stone fountain with a statue of a bird, surrounded by a ring of three small market stalls with striped awnings, string lights and potted flowers. Centered. $BG $STYLE" &
gen props "Sprite sheet of town map props, all separate: a round leafy oak tree, a tall pine tree, a pink blossom tree, a round green bush, an iron street lamp lit, a wooden bench, a short wooden fence segment, a flower bed, a barrel, a stack of crates, a wooden signpost, a stone well. $BG $STYLE" &
CHAR="Pixel-art RPG character walk-cycle sprite sheet: a 4 by 4 grid of equal square cells. Row 1: walking toward the camera (down), 4 frames. Row 2: walking left, 4 frames. Row 3: walking right, 4 frames. Row 4: walking away from the camera (up), 4 frames. The same small chibi character in every cell, full body, centered in its cell, same size in every cell, classic 3/4 top-down RPG proportions like Stardew Valley villagers. Flat pure magenta #FF00FF background, no grid lines, no shadows on the background, no magenta on the character. $STYLE"
gen char-a "$CHAR The character: young person with short brown hair, teal jacket, satchel." &
gen char-b "$CHAR The character: person with long red hair, mustard sweater, dark trousers." &
gen char-c "$CHAR The character: person with dark curly hair, lavender hoodie, round glasses." &
gen char-d "$CHAR The character: person with a blond ponytail, green apron over a white shirt." &
gen char-coord "$CHAR The character: an elder with a white beard, deep purple robe and a wooden staff." &
wait
